<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FLUSH </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BINARY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LOGS;</span></span>
